function esc(v) {
  if (v === null || v === undefined || v === '') return 'NULL';
  return "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "''") + "'";
}
function escNum(v) { const n = Number(v); return Number.isFinite(n) ? n : 0; }

// Lotes acotados: un INSERT por fila revienta la conexión con miles de leads,
// y un solo INSERT gigante también. 500 es el punto medio que ya usa WF14-Sheets.
// provider se resuelve EN SQL: si el lead aparece en stringee_calls es Stringee,
// si no y ya tuvo intentos es Asterisk, y si nunca se llamó queda NULL.
const BATCH = 500;
const rows = $input.all().map(i => i.json);
const cols = ['lead_id','full_name','phone','country','country_code','language','status','stage',
              'call_attempts','do_not_call','last_contacted_at','next_follow_up_at','provider','synced_at'];

const out = [];
for (let i = 0; i < rows.length; i += BATCH) {
  const chunk = rows.slice(i, i + BATCH);
  const values = chunk.map(r => {
    const providerExpr =
      `(CASE WHEN EXISTS(SELECT 1 FROM stringee_calls sc WHERE sc.lead_id = ${esc(r.lead_id)}) ` +
      `THEN 'stringee' WHEN ${escNum(r.call_attempts)} > 0 THEN 'asterisk' ELSE NULL END)`;
    return '(' + [
      esc(r.lead_id), esc(r.full_name), esc(r.phone), esc(r.country), esc(r.country_code),
      esc(r.language), esc(r.status), esc(r.stage), escNum(r.call_attempts), escNum(r.do_not_call),
      esc(r.last_contacted_at), esc(r.next_follow_up_at), providerExpr, esc(r.synced_at)
    ].join(',') + ')';
  }).join(',\n');

  const updates = cols.filter(c => c !== 'lead_id')
    .map(c => c === 'provider' ? 'provider=COALESCE(VALUES(provider), provider)' : `${c}=VALUES(${c})`)
    .join(',');

  out.push({ json: {
    sql: `INSERT INTO crm_leads (${cols.join(',')}) VALUES\n${values}\nON DUPLICATE KEY UPDATE ${updates};`,
    batch_size: chunk.length, batch_num: Math.floor(i / BATCH) + 1
  }});
}
console.log(`🧱 ${rows.length} leads → ${out.length} lote(s) de hasta ${BATCH}`);
return out;

// OJO: no sumar $input.all() acá — el nodo MySQL de arriba (Execute Query)
// reemplaza el contenido del item con el resultado de la query, no conserva
// batch_size. Hay que leerlo directo del nodo que arma los lotes.
const items = $('🧱 Lotes de 500 (crm_leads)').all();
let total = 0;
for (const it of items) total += Number(it.json.batch_size || 0);
const now = new Date().toISOString().slice(0, 19).replace('T', ' ');
console.log(`✅ crm_leads sincronizados: ${total} fila(s) en ${items.length} lote(s)`);
return [{ json: { rows_in: total, batches: items.length, synced_at: now } }];

// Conversión = cuenta de trader abierta. Se detecta por accountOpened=true o
// stage=INTERESTED (que es lo que WF3 escribe tras el 201 de cashstudio-account).
const rows = $input.all().map(i => i.json).filter(r => r.account_opened === 1);
const byCountry = rows.reduce((a, r) => { a[r.country] = (a[r.country]||0)+1; return a; }, {});
console.log(`📈 Conversiones detectadas: ${rows.length} | por país: ${JSON.stringify(byCountry)}`);
if (!rows.length) return [];
return rows.map(r => ({ json: r }));

