function esc(v) {
  if (v === null || v === undefined || v === '') return 'NULL';
  return "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "''") + "'";
}
function escNum(v) { const n = Number(v); return Number.isFinite(n) ? n : 0; }

// Igual que el WF15 original: lee el Call Log del worker y lo vuelca en stringee_calls.
// Esta rama NO toca el CRM — stringee_calls es la fuente de volumen/duración del
// proveedor de cuota fija, y también es la que define provider='stringee' en crm_leads.
// from_start_time va en SEGUNDOS (Stringee rechaza milisegundos).
function detectCountry(phone) {
  const p = String(phone || '').replace(/[^0-9]/g, '');
  if (p.startsWith('977')) return 'nepal';
  if (p.startsWith('52'))  return 'mexico';
  if (p.startsWith('91'))  return 'india';
  return 'unknown';
}

const data = $input.all()[0]?.json || {};
const calls = (data.data && data.data.calls) || [];
if (!calls.length) { console.log('Stringee: sin llamadas nuevas'); return []; }

const rows = calls.map(c => {
  const toNumber = String(c.to_number || '').replace(/[^0-9]/g, '');
  return {
    call_id: String(c.id || ''), phone: toNumber, country: detectCountry(toNumber),
    answered: Number(c.answer_time) > 0 ? 1 : 0,
    duration_secs: Number(c.answer_duration || 0),
    start_time: Number(c.start_time || 0),
    answer_time: Number(c.answer_time || 0),
    stop_time: Number(c.stop_time || 0)
  };
}).filter(r => r.call_id);

const BATCH = 200;
const out = [];
for (let i = 0; i < rows.length; i += BATCH) {
  const chunk = rows.slice(i, i + BATCH);
  const values = chunk.map(r => {
    const last10 = r.phone.slice(-10);
    // El lead_id sale del CRM ya sincronizado (crm_leads), no de panel_leads/Sheets.
    const leadSub = last10
      ? `(SELECT lead_id FROM crm_leads WHERE RIGHT(phone,10)=${esc(last10)} LIMIT 1)`
      : 'NULL';
    return '(' + [
      esc(r.call_id), leadSub, esc(r.phone), esc(r.country),
      escNum(r.answered), escNum(r.duration_secs),
      escNum(r.start_time), escNum(r.answer_time), escNum(r.stop_time)
    ].join(',') + ')';
  }).join(',\n');

  out.push({ json: { sql: `INSERT INTO stringee_calls
    (call_id, lead_id, phone, country, answered, duration_secs, start_time, answer_time, stop_time)
    VALUES\n${values}\n    ON DUPLICATE KEY UPDATE
      lead_id=COALESCE(VALUES(lead_id), lead_id), country=VALUES(country), answered=VALUES(answered),
      duration_secs=VALUES(duration_secs), answer_time=VALUES(answer_time), stop_time=VALUES(stop_time);`,
    batch_size: chunk.length }});
}
console.log(`📞 Stringee: ${rows.length} llamada(s) → ${out.length} lote(s)`);
return out;

// Mismo criterio que "📝 Contar filas (crm)": el nodo MySQL de arriba no
// conserva batch_size en su salida, hay que leerlo del nodo que armó los lotes.
const items = $('⚙️ Normalizar + SQL (stringee_calls)').all();
let total = 0;
for (const it of items) total += Number(it.json.batch_size || 0);
console.log(`✅ stringee_calls: ${total} fila(s) en ${items.length} lote(s)`);
return [{ json: { stringee_rows: total, synced_at: new Date().toISOString() } }];

// Un item por cada combinación status x dialCode. 7 status x 3 países = 21 requests base
// (cada uno pagina solo si total > 200). Usamos /api/leads (reporting, SIN cupo) — nunca /queue.
const STATUSES  = ['NOT_CONTACTED','ATTEMPTING','NO_ANSWER','CONTACTED','SNOOZED','UNREACHABLE','CLOSED'];
const DIALCODES = [
  { dialCode: '+91',  country: 'india'  },
  { dialCode: '+977', country: 'nepal'  },
  { dialCode: '+52',  country: 'mexico' }
];
const token = $json.accessToken;
if (!token) throw new Error('Sin accessToken — el login falló');

const out = [];
for (const s of STATUSES) for (const d of DIALCODES) {
  out.push({ json: { status: s, dialCode: d.dialCode, country: d.country, accessToken: token } });
}
return out;

// Recibe todas las páginas de todas las combinaciones status x dialCode y las aplana.
// El país se toma del prefijo real del teléfono (autoritativo), no del campo country
// del lead (puede venir null si se importó sin ese dato).
function detectCountry(phone) {
  const p = String(phone || '').replace(/[^0-9]/g, '');
  if (p.startsWith('977')) return { country: 'nepal',  code: '+977' };
  if (p.startsWith('52'))  return { country: 'mexico', code: '+52'  };
  if (p.startsWith('91'))  return { country: 'india',  code: '+91'  };
  return { country: 'unknown', code: '' };
}
function toMySqlDate(v) {
  if (!v) return null;
  const d = new Date(v);
  return isNaN(d) ? null : d.toISOString().slice(0, 19).replace('T', ' ');
}

const now = new Date().toISOString().slice(0, 19).replace('T', ' ');
const seen = new Set();
const out = [];
let pages = 0, raw = 0, dupes = 0, noId = 0;

for (const item of $input.all()) {
  pages++;
  const leads = (item.json && item.json.leads) || [];
  for (const l of leads) {
    raw++;
    const leadId = String(l.id || '').trim();
    if (!leadId) { noId++; continue; }
    if (seen.has(leadId)) { dupes++; continue; }   // un lead puede repetirse entre combos/páginas
    seen.add(leadId);

    const phone = String(l.phone || '').replace(/[^0-9+]/g, '');
    const geo = detectCountry(phone);

    out.push({ json: {
      lead_id          : leadId.slice(0, 64),
      full_name        : String(l.name || '').trim().slice(0, 160) || null,
      phone            : phone.slice(0, 32) || null,
      country          : geo.country,
      country_code     : geo.code,
      language         : String(l.language || '').trim().slice(0, 16) || null,
      status           : String(l.status || '').trim().toUpperCase().slice(0, 48) || null,
      stage            : String(l.stage || '').trim().toUpperCase().slice(0, 48) || null,
      call_attempts    : Number(l.attempts || 0) || 0,
      do_not_call      : l.doNotCall ? 1 : 0,
      last_contacted_at: toMySqlDate(l.lastContactedAt),
      next_follow_up_at: toMySqlDate(l.nextFollowUpAt),
      account_opened   : (l.accountOpened === true || String(l.stage||'').toUpperCase() === 'INTERESTED') ? 1 : 0,
      account_opened_at: toMySqlDate(l.accountOpenedAt || l.updatedAt),
      synced_at        : now
    }});
  }
}

const byCountry = out.reduce((a, r) => { a[r.json.country] = (a[r.json.country]||0)+1; return a; }, {});
console.log(`📥 CRM: ${pages} respuesta(s) página → ${raw} filas crudas → ${out.length} leads únicos ` +
            `(dupes ${dupes}, sin id ${noId}) | por país: ${JSON.stringify(byCountry)}`);
if (!out.length) return [];
return out;
